def _runtime_root() -> Path:
    raw = zlib.decompress(base64.b85decode(PAYLOAD))
    digest = hashlib.sha256(raw).hexdigest()[:16]
    if os.name == "nt":
        base = Path(os.environ.get("LOCALAPPDATA") or (Path.home() / "AppData" / "Local")) / "PCL" / "runtime" / "single"
    else:
        base = Path(os.environ.get("PCL_SINGLE_HOME") or (Path.home() / ".cache" / "pcl-launcher" / "single"))
    try:
        base.mkdir(parents=True, exist_ok=True)
    except OSError:
        base = Path(tempfile.gettempdir()) / "pcl-launcher-single"
        base.mkdir(parents=True, exist_ok=True)
    target = base / digest
    marker = target / ".complete"
    if marker.is_file():
        return target
    tmp = Path(tempfile.mkdtemp(prefix="extract-", dir=str(base)))
    try:
        with zipfile.ZipFile(io.BytesIO(raw)) as zf:
            for member in zf.infolist():
                dest = (tmp / member.filename).resolve()
                if dest != tmp.resolve() and tmp.resolve() not in dest.parents:
                    continue
                zf.extract(member, tmp)
        (tmp / ".complete").write_text(APP_VERSION, encoding="utf-8")
        if target.exists():
            shutil.rmtree(target, ignore_errors=True)
        os.replace(tmp, target)
    except Exception:
        shutil.rmtree(tmp, ignore_errors=True)
        raise
    return target


def main() -> None:
    root = _runtime_root()
    sys.path.insert(0, str(root))
    sys.argv[0] = str(root / "pcl.py")
    runpy.run_path(str(root / "pcl.py"), run_name="__main__")


if __name__ == "__main__":
    main()
